nav='<nav class="draft-toc" aria-label="Оглавление"><button id="toc-toggle" aria-expanded="false" aria-controls="toc-links">Оглавление</button><div id="toc-links">'+''.join('<a href="#'+k+'">'+title+'</a>' for k,title,_ in sections)+'</div></nav>'
page='<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Red Wings · утренний отчёт 10 ноября 2026</title><style>'+css+'</style></head><body><div class="draft-layout">'+nav+'<main><h1>Red Wings: результаты ночного исследования</h1><p>10 ноября 2026 · входы заморожены в 09:30 МСК</p>'+''.join(s[2] for s in sections)+'</main></div><script id="map-data" type="application/json">'+json.dumps(maps,ensure_ascii=False).replace('</','<\\/')+'</script><script>'+js+'</script></body></html>'
(OUT/'morning-report.html').write_text(page)
(OUT/'sources_manifest.json').write_text(json.dumps({'root':ROOT,'methods':METHODS,'freeze':freeze,'inputs':manifest,'upstream_references':inputmeta,'acceptance_events':events,'purpose':'presentation only; no new model computation'},ensure_ascii=False,indent=2))
(OUT/'report_data.json').write_text(json.dumps({'common_rows':common,'inventory35':inv,'finite_networks':union,'requirements':req,'claims':claims,'competitors':compet},ensure_ascii=False,indent=2))
# Deep-anchor native QA views reuse the exact final styles, data and renderer; no server.
for name,k in [('qa-map','networks'),('qa-deep','budget')]:
 sectionhtml=next(x[2] for x in sections if x[0]==k)
 if k=='networks':sectionhtml=sectionhtml[:sectionhtml.index('<article class="program" id="C02"')]
 # Keep required controller nodes outside the excerpt for the same unchanged script.
 controls=''
 for ident,tag in [('network-select','select'),('selected-map','div'),('selected-routes','div'),('program-search','input'),('program-count','span')]:
  if 'id="'+ident+'"' not in sectionhtml:controls+='<'+tag+' id="'+ident+'" hidden></'+tag+'>'
 (OUT/(name+'.html')).write_text('<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>'+css+'</style><body><div class="draft-layout">'+nav+'<main>'+sectionhtml+'</main></div>'+controls+'<script id="map-data" type="application/json">'+json.dumps(maps,ensure_ascii=False).replace('</','<\\/')+'</script><script>'+js+'</script></body></html>')
print(json.dumps({'sections':len(sections),'programs':len(inv),'maps_available':len(maps['maps']),'common_rows':len(common),'bytes':len(page.encode()),'output':str(OUT/'morning-report.html')}))
